      </button>
    </article>
  );
}

function App() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [orderId, setOrderId] = useState(null);
  const [sending, setSending] = useState(false);
  const { cart, addToCart, clearCart, count, totalPrice } = useCart();
  const ready = !loading && !error;

  async function loadProducts() {
    setError(null);
    setLoading(true);

    try {
      const response = await fetch("/api/products");

      if (!response.ok) {
        throw new Error("Сервер " + response.status + " хариу буцаалаа");
      }

      setProducts(await response.json());
    } catch (problem) {
      setError(problem.message);
    } finally {
      setLoading(false);
    }
  }

  async function placeOrder() {
    setSending(true);

    try {
      const response = await fetch("/api/orders", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ items: cart, total: totalPrice }),
      });

      if (!response.ok) {
        throw new Error("Захиалга илгээгдсэнгүй");
      }

      const saved = await response.json();
      setOrderId(saved.id);
      clearCart();
    } catch (problem) {
      setError(problem.message);
    } finally {
      setSending(false);
    }
  }

  useEffect(() => {
    loadProducts();
  }, []);

  return (
    <main>
      <header className="topbar">
        <h1>Shop.mn</h1>
        <button
          className="btn-refresh"
          data-testid="refresh"
          onClick={loadProducts}
          disabled={loading}
        >
          Шинэчлэх
        </button>
        <span className="cart-count" data-testid="cart-count">{count}</span>
      </header>

      {loading ? <p data-testid="loading">Ачаалж байна…</p> : null}

      {error ? (
        <div className="error" data-testid="error">
          <p>{error}</p>
        </div>
      ) : null}
      {ready ? (
        <section className="product-grid" data-testid="grid">
          {products.map((product) => (
            <ProductCard key={product.id} product={product} onAdd={addToCart} />
          ))}
        </section>
      ) : null}

      <section className="cart">
        <h2>Сагс</h2>
        <p className="cart-total" data-testid="cart-total">{formatPrice(totalPrice)}</p>
        {orderId ? (
          <p className="ok" data-testid="order-ok">Захиалга #{orderId} баталгаажлаа.</p>
        ) : null}

        <button
          className="btn-add"
          data-testid="place-order"
          onClick={placeOrder}
          disabled={sending || count === 0}
        >
          {sending ? "Илгээж байна…" : "Захиалга илгээх"}
        </button>
      </section>
    </main>
  );
}

createRoot(document.getElementById("root")).render(<App />);
